const body = $input.first().json.body ?? $input.first().json;

const asList = (v) => {
  if (Array.isArray(v)) return v.filter(Boolean).join(', ');
  if (v == null || v === '') return '';
  return String(v);
};

const escapeHtml = (v) =>
  String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const resume = body.resume && typeof body.resume === 'object' ? body.resume : null;
const hasResume = Boolean(resume && resume.base64);
const resumeFileName = resume?.fileName || '';
const resumeMimeType = resume?.mimeType || 'application/octet-stream';

const data = {
  submittedAt: body.submittedAt || new Date().toISOString(),
  role: body.role || '',
  fullName: body.fullName || '',
  email: body.email || '',
  phone: body.phone || '',
  cityState: body.cityState || '',
  localToMaryland: body.localToMaryland || '',
  availableToStart: body.availableToStart || '',
  availability: asList(body.availability),
  compensationOk: body.compensationOk || '',
  yearsExperience: body.yearsExperience || '',
  tools: body.tools || '',
  supportedAreas: asList(body.supportedAreas),
  fitWhy: body.fitWhy || '',
  prioritizeTasks: body.prioritizeTasks || '',
  organizedExample: body.organizedExample || '',
  linkedin: body.linkedin || '',
  openToCall: body.openToCall || '',
  referencesAvailable: body.referencesAvailable || '',
  resumeFileName,
  resumeMimeType,
  hasResume,
};

const e = Object.fromEntries(
  Object.entries(data).map(([k, v]) => [k, escapeHtml(v)])
);

const row = (label, value) =>
  `<tr><td style="padding:8px 12px;border-bottom:1px solid #eee;color:#666;width:38%;vertical-align:top;">${label}</td><td style="padding:8px 12px;border-bottom:1px solid #eee;color:#151121;vertical-align:top;">${value || '—'}</td></tr>`;

data.internalHtml = `<!DOCTYPE html><html><body style="margin:0;padding:0;background:#f6f3fb;font-family:Arial,Helvetica,sans-serif;">
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f6f3fb;padding:32px 16px;">
    <tr><td align="center">
      <table role="presentation" width="640" cellspacing="0" cellpadding="0" style="background:#ffffff;border-radius:16px;overflow:hidden;border:1px solid #d1c4e9;">
        <tr><td style="background:#151121;padding:20px 28px;color:#fff;font-size:14px;letter-spacing:1px;">N NATURAL HAIR STUDIO · CAREERS</td></tr>
        <tr><td style="padding:28px;">
          <p style="margin:0 0 8px;font-size:13px;color:#e04b00;font-weight:bold;text-transform:uppercase;letter-spacing:1px;">New application</p>
          <h1 style="margin:0 0 16px;font-size:28px;line-height:1.2;color:#151121;">${e.fullName}</h1>
          <p style="display:inline-block;margin:0 0 24px;padding:8px 14px;border-radius:999px;background:#e1ff00;color:#1a1626;font-size:13px;font-weight:bold;">${e.role || 'Open role'}</p>
          <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border:1px solid #eee;border-radius:12px;overflow:hidden;">
            ${row('Submitted', e.submittedAt)}
            ${row('Email', e.email)}
            ${row('Phone', e.phone)}
            ${row('City / State', e.cityState)}
            ${row('Local to Maryland', e.localToMaryland)}
            ${row('Available to start', e.availableToStart)}
            ${row('Availability', e.availability)}
            ${row('Compensation OK', e.compensationOk)}
            ${row('Years experience', e.yearsExperience)}
            ${row('Tools', e.tools)}
            ${row('Supported areas', e.supportedAreas)}
            ${row('LinkedIn', e.linkedin)}
            ${row('Open to intro call', e.openToCall)}
            ${row('References available', e.referencesAvailable)}
            ${row('Resume', e.resumeFileName || (data.hasResume ? 'Attached' : 'Not provided'))}
          </table>
          <h2 style="margin:28px 0 8px;font-size:18px;color:#e04b00;">Short answers</h2>
          <p style="margin:0 0 4px;font-size:12px;color:#666;text-transform:uppercase;letter-spacing:0.5px;">Why this role</p>
          <p style="margin:0 0 16px;color:#151121;white-space:pre-wrap;">${e.fitWhy || '—'}</p>
          <p style="margin:0 0 4px;font-size:12px;color:#666;text-transform:uppercase;letter-spacing:0.5px;">Prioritizing tasks</p>
          <p style="margin:0 0 16px;color:#151121;white-space:pre-wrap;">${e.prioritizeTasks || '—'}</p>
          <p style="margin:0 0 4px;font-size:12px;color:#666;text-transform:uppercase;letter-spacing:0.5px;">Organization example</p>
          <p style="margin:0;color:#151121;white-space:pre-wrap;">${e.organizedExample || '—'}</p>
        </td></tr>
      </table>
    </td></tr>
  </table>
</body></html>`;

data.applicantHtml = `<!DOCTYPE html><html><body style="margin:0;padding:0;background:#f6f3fb;font-family:Arial,Helvetica,sans-serif;">
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f6f3fb;padding:32px 16px;">
    <tr><td align="center">
      <table role="presentation" width="640" cellspacing="0" cellpadding="0" style="background:#ffffff;border-radius:16px;overflow:hidden;border:1px solid #d1c4e9;">
        <tr><td style="background:#151121;padding:20px 28px;color:#fff;font-size:14px;letter-spacing:1px;">N NATURAL HAIR STUDIO</td></tr>
        <tr><td style="padding:28px;">
          <p style="margin:0 0 8px;font-size:13px;color:#e04b00;font-weight:bold;text-transform:uppercase;letter-spacing:1px;">Application received</p>
          <h1 style="margin:0 0 16px;font-size:28px;line-height:1.2;color:#151121;">Thanks, ${e.fullName || 'there'}.</h1>
          <p style="margin:0 0 16px;font-size:16px;line-height:1.5;color:#151121;">We received your application for <strong>${e.role || 'an open role'}</strong> at N Natural Hair Studio.</p>
          <p style="margin:0 0 16px;font-size:16px;line-height:1.5;color:#151121;">Our team reviews every application carefully. If your experience looks like a fit, we will reach out about next steps.</p>
          <p style="margin:0 0 24px;padding:14px 16px;background:#d1c4e9;border-radius:12px;font-size:14px;color:#151121;">No action is needed from you right now. Keep an eye on <strong>${e.email}</strong> (and spam, just in case).</p>
          <p style="margin:0;font-size:14px;line-height:1.5;color:#666;">With care,<br/><strong style="color:#151121;">N Natural Hair Studio</strong><br/>Careers Team</p>
        </td></tr>
        <tr><td style="padding:16px 28px;background:#151121;color:#c6c9ab;font-size:12px;">nnaturalhairstudio.com</td></tr>
      </table>
    </td></tr>
  </table>
</body></html>`;

const out = { json: data };
if (hasResume) {
  out.binary = {
    resume: {
      data: String(resume.base64).replace(/^data:[^;]+;base64,/, ''),
      mimeType: resumeMimeType,
      fileName: resumeFileName || 'resume',
    },
  };
}
return [out];

const prep = $('Prepare Application').first();
return [{
  json: { ...prep.json },
  binary: prep.binary ? { ...prep.binary } : undefined,
}];
